import{_ as o,I as e,g as r,j as l}from"./chunks/framework.CjoWWfVe.js";const h=JSON.parse('{"title":"Мастерская (Активы)","description":"Учет оборудования, инструментов и расчет их износа в ОмниКрафт ЕРП. Трансформируем траты в инвестиции.","frontmatter":{"title":"Мастерская (Активы)","description":"Учет оборудования, инструментов и расчет их износа в ОмниКрафт ЕРП. Трансформируем траты в инвестиции.","order":4},"headers":[],"relativePath":"ru/docs/spaces/production/workshop.md","filePath":"ru/docs/spaces/production/workshop.md"}'),a={name:"ru/docs/spaces/production/workshop.md"};function s(n,t,i,c,d,p){return e(),r("div",null,[...t[0]||(t[0]=[l('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🛠️-мастерская-учет-активов-и-оборудования" tabindex="-1">🛠️ Мастерская: Учет активов и оборудования <a class="header-anchor" href="#🛠️-мастерская-учет-активов-и-оборудования" aria-label="Permalink to &quot;🛠️ Мастерская: Учет активов и оборудования&quot;">​</a></h1><p>Вкладка <strong>«Мастерская»</strong> — это реестр вашего долгосрочного имущества. Это не просто инвентаризационный список вещей, которые лежат у вас в помещении. Это ваш производственный фундамент — материальные активы, формирующие значительную часть стоимости вашего бизнеса (Капитала).</p><p>Здесь вы управляете станками, дорогостоящим инструментом, электроникой и недвижимостью, используемой в работе.</p><hr><h2 id="💎-экономическии-смысл-трансформация-трат-в-инвестиции" tabindex="-1">💎 Экономический смысл: Трансформация трат в инвестиции <a class="header-anchor" href="#💎-экономическии-смысл-трансформация-трат-в-инвестиции" aria-label="Permalink to &quot;💎 Экономический смысл: Трансформация трат в инвестиции&quot;">​</a></h2><p>В профессиональном учете покупка дорогого оборудования воспринимается иначе, чем в быту. ОмниКрафт ЕРП опирается на два железных экономических правила:</p><ol><li><strong>Покупка станка — это не потеря денег.</strong> Когда вы покупаете лазерный гравер или муфельную печь за <code>150 000 ₽</code>, вы не становитесь беднее. Вы просто перекладываете ценность из кошелька (кассы) на полку мастерской. Капитал вашего бизнеса остается неизменным, просто <code>150 000 ₽</code> из формы «свободные деньги» перешли в форму «оборудование».</li><li><strong>Как инструмент окупает себя без рутинных расчетов (Амортизация).</strong> В отличие от сложных промышленных систем, где вам пришлось бы высчитывать машино-часы и вбивать время работы каждого сверла до секунды, ОмниКрафт ЕРП идет по бережливому пути: <ul><li>Программа сама рассчитывает и показывает в панели статистики <strong>общую точную сумму износа всей мастерской в месяц</strong> (например, <code>8 500 ₽/мес</code>).</li><li>Опираясь на эту твердую цифру и ваш средний объем производства, вы можете легко установить усредненный глобальный норматив по износу в накладных расходах в Настройках (например, фиксированный износ на единицу или процент).</li><li>В Калькуляторе вы можете регулировать этот износ коэффициентами для конкретных изделий (например, <code>1.5</code> для трудоемкого пошива или <code>0.0</code> для брелока). Клиент оплачивает износ при покупке, а вы постепенно возвращаете вложенные в станки средства.</li></ul></li></ol><hr><h2 id="🚀-практическое-использование-внесение-имущества" tabindex="-1">🚀 Практическое использование: Внесение имущества <a class="header-anchor" href="#🚀-практическое-использование-внесение-имущества" aria-label="Permalink to &quot;🚀 Практическое использование: Внесение имущества&quot;">​</a></h2><p>В ОмниКрафт ЕРП внедрен принцип <strong>«Оценочной точки старта»</strong>. Если вы вносите старый инструмент, просто оцените его так, как если бы выставляли его на продажу прямо сегодня. Укажите эту остаточную стоимость, примерный оставшийся срок службы — и работайте дальше.</p><blockquote><p><em>[Место для скриншота: Общий вид вкладки &quot;Мастерская&quot; с открытой формой добавления]</em></p></blockquote><p>Чтобы добавить позицию, нажмите кнопку <strong>«Внести актив»</strong> в верхней части экрана.</p><h3 id="базовые-поля" tabindex="-1">Базовые поля <a class="header-anchor" href="#базовые-поля" aria-label="Permalink to &quot;Базовые поля&quot;">​</a></h3><ul><li><strong>Название актива:</strong> Краткое и понятное имя. <em>Пример: Швейная машина Durkopp Adler, 3D-принтер Anycubic, Гончарный круг.</em></li><li><strong>Категория:</strong> Группа для наведения порядка и аналитики (Оборудование, Инструменты, Помещение).</li><li><strong>Текущая стоимость:</strong> Цена покупки (для новых вещей) или ваша оценка на сегодняшний день (для старых).</li><li><strong>Срок службы (лет):</strong> Сколько, по вашему мнению, эта вещь еще прослужит. <blockquote><p><em>Пример: Вы купили 3D-принтер за <code>45 000 ₽</code> и планируете использовать его 3 года. Программа автоматически вычислит, что принтер теряет в цене <code>1 250 ₽</code> в месяц.</em></p></blockquote></li></ul><h3 id="умные-параметры-чекбоксы" tabindex="-1">Умные параметры (Чекбоксы) <a class="header-anchor" href="#умные-параметры-чекбоксы" aria-label="Permalink to &quot;Умные параметры (Чекбоксы)&quot;">​</a></h3><p>В форме есть две особые галочки, которые полностью меняют логику учета позиции, защищая вас от лишней бухгалтерской рутины.</p><div class="tip custom-block"><p class="custom-block-title">Галочка «Расходник» (Свобода от микроменеджмента)</p><p>Зачем рассчитывать амортизацию на 5 лет для фрезы, набора сверл или банки дорогой профессиональной химии за <code>5 000 ₽</code>? Отметьте такую позицию как <strong>«Расходник»</strong>. Программа спишет эти <code>5 000 ₽</code> сразу в расходы бизнеса (в ДДС), минуя долгий процесс амортизации. Мелочевка будет учтена в общих тратах, но не станет засорять ваш серьезный баланс активов. Срок службы для расходников указывать не нужно.</p></div><div class="tip custom-block"><p class="custom-block-title">Галочка «Безвозмездное поступление» (Магия денег из воздуха)</p><p>Что делать, если вы принесли старую наковальню из личного гаража, вам подарили набор штампов или вы выиграли государственный грант на закупку фанеры на <code>200 000 ₽</code>? Активируйте галочку <strong>«Безвозмездное поступление»</strong>. Оборудование встанет на баланс бизнеса (ваш Капитал вырастет, так как теперь вы владеете дорогой вещью), но программа <strong>не спишет деньги из кассы ДДС</strong>, потому что физически вы за нее не платили.</p></div><hr><h2 id="🔄-жизненныи-цикл-активов-деиствия" tabindex="-1">🔄 Жизненный цикл активов (Действия) <a class="header-anchor" href="#🔄-жизненныи-цикл-активов-деиствия" aria-label="Permalink to &quot;🔄 Жизненный цикл активов (Действия)&quot;">​</a></h2><p>В процессе работы с оборудованием всегда происходят изменения. Чтобы ваш учет оставался кристально чистым и отражал реальность, используйте следующие сценарии (доступны по кнопке ✏️ «Редактировать» на карточке актива в таблице).</p><h3 id="_1-переоценка-удорожание-инструмента" tabindex="-1">1. Переоценка (Удорожание инструмента) <a class="header-anchor" href="#_1-переоценка-удорожание-инструмента" aria-label="Permalink to &quot;1. Переоценка (Удорожание инструмента)&quot;">​</a></h3><p>Допустим, три года назад вы купили дубовый верстак за <code>30 000 ₽</code>. Сегодня из-за инфляции и стоимости дерева такой же б/у верстак стоит <code>50 000 ₽</code>.</p><ul><li><strong>Действие:</strong> Вы просто редактируете поле «Текущая стоимость».</li><li><strong>Результат:</strong> Капитал вашего бизнеса справедливо вырастет, при этом касса (ДДС) затронута не будет, так как новой покупки не происходило.</li></ul><h3 id="_2-текущии-ремонт-vs-капитальная-модернизация" tabindex="-1">2. Текущий ремонт vs Капитальная модернизация <a class="header-anchor" href="#_2-текущии-ремонт-vs-капитальная-модернизация" aria-label="Permalink to &quot;2. Текущий ремонт vs Капитальная модернизация&quot;">​</a></h3><p>Важно разделять два типа расходов на станки, чтобы не сломать себестоимость.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Тип операции</th><th style="text-align:left;">Пример из жизни</th><th style="text-align:left;">Как проводить в программе</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Текущее обслуживание</strong></td><td style="text-align:left;">Заточка ножей рубанка за <code>2 000 ₽</code>, замена масла, вызов наладчика.</td><td style="text-align:left;">Проводится строго во вкладке <strong>ДДС</strong> как обычный расход. <em>Не плюсуйте эти суммы к стоимости станка, чтобы не раздувать баланс воздухом!</em></td></tr><tr><td style="text-align:left;"><strong>Модернизация (Апгрейд)</strong></td><td style="text-align:left;">Установка лазерного модуля на ЧПУ-станок за <code>30 000 ₽</code>. Это повысило рыночную ценность станка.</td><td style="text-align:left;">Сначала проводите расход <code>30 000 ₽</code> в <strong>ДДС</strong>. Затем идете в <strong>Мастерскую</strong> и вручную плюсуете <code>30 000 ₽</code> к стоимости станка, при необходимости продлевая срок его службы.</td></tr></tbody></table><h3 id="_3-статусы-и-списание" tabindex="-1">3. Статусы и Списание <a class="header-anchor" href="#_3-статусы-и-списание" aria-label="Permalink to &quot;3. Статусы и Списание&quot;">​</a></h3><p>Каждому активу можно присвоить статус: <strong>В работе</strong>, <strong>В ремонте</strong> или <strong>В резерве</strong>. Это помогает понимать, на что можно рассчитывать в производстве.</p><div class="warning custom-block"><p class="custom-block-title">Списание сломанного или утерянного</p><p>Если инструмент безвозвратно сломался, потерялся или вы его выбросили — нажмите иконку корзины 🗑️ рядом с ним. Программа <strong>снимет его с баланса</strong>. Исторические траты в ДДС сохранятся, но общая стоимость вашей мастерской (Капитал) уменьшится на остаточную стоимость этого предмета.</p></div><hr><h2 id="🎛️-управление-в-таблице" tabindex="-1">🎛️ Управление в таблице <a class="header-anchor" href="#🎛️-управление-в-таблице" aria-label="Permalink to &quot;🎛️ Управление в таблице&quot;">​</a></h2><p>Когда ваш парк оборудования разрастется до десятков позиций, программа позволит легко в нем ориентироваться.</p><blockquote><p><em>[Место для скриншота: Таблица оборудования с открытым фильтром по столбцу]</em></p></blockquote><ul><li><strong>Фильтрация и сортировка:</strong> Наведите курсор на заголовок любой колонки (например, «Текущая стоимость») и нажмите на появившуюся иконку фильтра. Вы можете в пару кликов оставить на экране только станки, которые находятся «В ремонте», или отсортировать имущество от самого дорогого к дешевому.</li><li><strong>Быстрый сброс:</strong> Если вы запутались в фильтрах, над таблицей появится кнопка <strong>«Сбросить фильтры»</strong>, которая мгновенно вернет список в идеальный исходный вид.</li><li><strong>Справочник категорий:</strong> Нажмите иконку шестеренки/карандаша рядом с выбором категории в форме добавления. Программа позволяет переименовывать базовые категории и создавать свои собственные, подстраиваясь под любую нишу (например, создать категории <em>«Гончарные круги»</em>, <em>«Фрезы»</em>, <em>«Оптика»</em>).</li></ul><hr><h2 id="📊-просмотр-статистики" tabindex="-1">📊 Просмотр статистики <a class="header-anchor" href="#📊-просмотр-статистики" aria-label="Permalink to &quot;📊 Просмотр статистики&quot;">​</a></h2><p>Для собственника бизнеса важно видеть общую картину, а не только строки в таблице. Нажмите на иконку статистики 📊 в верхнем ряду кнопок, чтобы открыть аналитическую боковую панель.</p><blockquote><p><em>[Место для скриншота: Боковая панель (или модальное окно на мобильных) статистики Мастерской]</em></p></blockquote><p>Панель собирает все данные воедино и показывает:</p><ol><li><strong>Остаточную стоимость имущества:</strong> Итоговая сумма в рублях. Ровно столько стоят ваши физические активы на текущий день с учетом инфляции и износа.</li><li><strong>Текущий износ в месяц:</strong> Сумма, на которую ваш парк оборудования дешевеет каждый месяц. Именно эту цифру программа компенсирует вам через накладные расходы в себестоимости.</li><li><strong>Структуру капитала:</strong> Удобные прогресс-бары показывают, в каких категориях сосредоточено больше всего денег (например, 70% ценности бизнеса — это оборудование, 20% — дорогие инструменты, 10% — мебель).</li><li><strong>Активы в резерве:</strong> Быстрая сводка имущества, которое временно выведено из эксплуатации.</li></ol>',42)])])}const u=o(a,[["render",s]]);export{h as __pageData,u as default};
